   918                  *pvalue = result;
   919              }
   920
   921              /* If the caller has passed the `pvalue_len` pointer, store the
   922               * number of consumed bytes in it and do NOT consume those bytes,
   923               * since the caller has all the information it needs to perform
   924               * the consuming process itself. */
   925              if(pvalue_len) {
   926                  *pvalue_len = 1 + i;
   927              } else {
   928                  /* If the caller did not provide the `pvalue_len` pointer,
   929                   * it will not have the possibility to advance the file
   930                   * pointer, because it will not know how many bytes it needs
   931                   * to consume. This is why we handle such situation here
   932                   * automatically. */
   933                  if(ARCHIVE_OK != consume(a, 1 + i)) {
   934                      return 0;
   935                  }
   936              }
   937
   938              /* End of decoding process, return success. */
   939              return 1;
   940          }
   941      }
